// Get Returns basic details about the server.
//
// Returns basic details about the server as well as your authentication status.
//
// This is the only API request that does *not* require authentication.
//
// Corresponds with GET / (the `Get` operationId).
func (c *Client) Get(ctx context.Context, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewGetRequest(c.Server)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

